.config/zed/settings.json:
{
  "active_pane_modifiers": {
    "inactive_opacity": 0.2
  },
  "agent": {
    "button": false,
    "default_model": {
      "effort": "medium",
      "enable_thinking": true,
      "model": "gpt-5.6-sol",
      "provider": "openai"
    },
    "dock": "right"
  },
  "auto_install_extensions": {
    "catppuccin-icons": true,
    "crates-lsp": true,
    "gleam": true,
    "islands-theme": true,
    "jetbrains-new-ui-icons": true,
    "nix": true,
    "nu": true,
    "tombi": true,
    "toml": true
  },
  "autosave": "on_focus_change",
  "base_keymap": "JetBrains",
  "buffer_font_family": "Berkeley Mono",
  "buffer_font_size": 10,
  "buffer_font_weight": 200,
  "buffer_line_height": {
    "custom": 1.1
  },
  "centered_layout": {
    "left_padding": 0,
    "right_padding": 0
  },
  "close_on_file_delete": true,
  "collaboration_panel": {
    "dock": "left"
  },
  "completions": {
    "words": "enabled"
  },
  "cursor_blink": false,
  "diagnostics": {
    "button": false,
    "inline": {
      "enabled": true
    }
  },
  "git": {
    "inline_blame": {
      "enabled": false
    },
    "path_style": "file_path_first"
  },
  "git_panel": {
    "dock": "left"
  },
  "gutter": {
    "bookmarks": false,
    "breakpoints": false,
    "folds": false,
    "line_numbers": false,
    "runnables": false
  },
  "icon_theme": {
    "dark": "Catppuccin Frappé",
    "light": "JetBrains New UI Icons (Light)",
