  },
  "inlay_hints": {
    "enabled": true,
    "show_parameter_hints": false
  },
  "languages": {
    "Nix": {
      "format_on_save": "on",
      "formatter": {
        "external": {
          "command": "/nix/store/bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb-nixfmt-1.1.0/bin/nixfmt"
        }
      },
      "language_servers": [
        "nil",
        "!nixd"
      ]
    },
    "Python": {
      "format_on_save": "on"
    },
    "TOML": {
      "language_servers": [
        "crates-lsp",
        "tombi",
        "..."
      ]
    }
  },
  "lsp": {
    "basedpyright": {
      "settings": {
        "basedpyright.analysis": {
          "typeCheckingMode": "standard"
        }
      }
    },
    "lua-language-server": {
      "settings": {
        "Lua": {
          "diagnostics": {
            "globals": [
              "vim"
            ]
          }
        }
      }
    },
    "rust-analyzer": {
      "initialization_options": {
        "check": {
          "command": "clippy"
        }
      }
    },
    "tombi": {
      "settings": {
        "lint": {
          "rules": {
            "tables-out-of-order": "off"
          }
        }
      }
    }
  },
  "outline_panel": {
    "button": false,
    "default_width": 240,
    "dock": "left",
    "indent_size": 10,
    "scrollbar": {
      "show": "never"
    }
  },
  "preview_tabs": {
    "enable_keep_preview_on_code_navigation": true,
    "enable_preview_from_file_finder": true
  },
  "project_panel": {
    "button": false,
    "default_width": 200,
    "diagnostic_badges": true,
    "dock": "left",
    "entry_spacing": "standard",
    "git_status_indicator": true,
    "hide_gitignore": true,
    "hide_root": true,
    "indent_size": 16,
    "scrollbar": {
      "show": "never"
    }
  },
  "scrollbar": {
    "show": "never"
  },
  "search_wrap": false,
  "session": {
    "trust_all_worktrees": true
  },
  "sticky_scroll": {
    "enabled": true
  },
  "tab_bar": {
    "show_nav_history_buttons": false,
    "show_tab_bar_buttons": false
  },
  "tab_size": 2,
  "tabs": {
    "activate_on_close": "neighbour",
    "file_icons": true,
    "git_status": true,
    "show_close_button": "hidden",
    "show_diagnostics": "all"
  },
  "telemetry": {
    "metrics": false
  },
  "terminal": {
    "shell": {
      "program": "/nix/store/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-nushell-0.108.0/bin/nu"
    }
  },
  "theme": {
    "dark": "Islands Dark",
    "light": "Islands Light",
    "mode": "dark"
  },
  "theme_overrides": {
    "Islands Dark": {
      "players": [
        {
          "background": "#808080ff",
          "cursor": "#808080ff",
          "selection": "#8080803d"
        }
      ]
    }
  },
  "title_bar": {
    "show_onboarding_banner": false,
    "show_sign_in": false,
    "show_user_menu": false,
    "show_user_picture": false
  },
  "toolbar": {
    "breadcrumbs": false,
    "quick_actions": false
  },
  "ui_font_family": "Inter",
  "ui_font_size": 12,
  "unstable.ui_density": "compact",
  "use_system_prompts": false,
  "vertical_scroll_margin": 20,
  "vim": {
    "highlight_on_yank_duration": 0
  },
  "vim_mode": true
}

